callGraph.callee:
(
        await db.workBlock.findMany({
          where: { taskId: task.id, recurrenceKey: { not: null } },
          select: { recurrenceKey: true },
        })
      ).map

latestRuns
    .map((run) => {
      const task = taskByLatestRunId.get(run.id);

      if (!task) {
        return null;
      }

      if (run.status === RunStatus.WaitingForInput) {
        return {
          id: run.id,
          kind: "input" as const,
          actionType: "Input requested",
          riskLevel: "medium",
          sourceTaskTitle: task.title,
          sourceTaskId: task.id,
          workspaceId: task.workspaceId,
          currentRunLabel: run.runtimeRunRef ?? run.id,
          detail: "Operator reply required",
          summary: run.pendingInputPrompt ?? "The agent is waiting for guidance before it can continue.",
          consequence: "Execution stays paused until an operator replies from the workbench.",
          sortAt: run.updatedAt,
        };
      }

      return {
        id: run.id,
        kind: "recovery" as const,
        actionType: "Recovery needed",
        riskLevel: run.status === RunStatus.Failed ? "critical" : run.retryable ? "high" : "medium",
        sourceTaskTitle: task.title,
        sourceTaskId: task.id,
        workspaceId: task.workspaceId,
        currentRunLabel: run.runtimeRunRef ?? run.id,
        detail: `Latest run ${run.status}`,
        summary:
          run.status === RunStatus.Failed
            ? "The latest run stopped before finishing and needs an operator recovery prompt."
            : "The latest run was cancelled and needs operator review before restarting.",
        consequence: "Execution will not resume until someone restarts or recovers the run from the workbench.",
        sortAt: run.updatedAt,
      };
    })
    .filter

[
              makeEvidence({
                label: copy.requestedGuidance,
                value: planExecution.message ?? `Continue work on ${taskTitle}`,
                tone: "warning",
              }),
              ...sharedEvidence,
            ].slice

[
          makeEvidence({
            label: copy.requestedGuidance,
            value: currentRun.pendingInputPrompt ?? `Continue work on ${taskTitle}`,
            tone: "warning",
          }),
          ...sharedEvidence,
        ].slice

[
          makeEvidence({
            label: copy.pendingApproval,
            value: approvals[0]?.title ?? copy.approvalRequest,
            tone: "warning",
          }),
          ...(approvals[0]?.summary
            ? [
                makeEvidence({
                  label: copy.approvalSummary,
                  value: approvals[0].summary,
                  tone: "warning",
                }),
              ]
            : []),
          ...sharedEvidence,
        ].slice

[
          ...(latestToolIssue
            ? [
                makeEvidence({
                  label: copy.latestToolIssue,
                  value: latestToolIssue.errorSummary ?? `${latestToolIssue.toolName} ended in ${latestToolIssue.status}`,
                  tone: "critical",
                }),
              ]
            : []),
          ...sharedEvidence,
        ].slice

allConversationEntries
    .slice()
    .sort((left, right) => {
      const leftRuntimeTs = left.runtimeTs?.getTime() ?? Number.POSITIVE_INFINITY;
      const rightRuntimeTs = right.runtimeTs?.getTime() ?? Number.POSITIVE_INFINITY;

      if (leftRuntimeTs !== rightRuntimeTs) {
        return leftRuntimeTs - rightRuntimeTs;
      }

      const leftRunCreatedAt = left.run.createdAt.getTime();
      const rightRunCreatedAt = right.run.createdAt.getTime();
      if (leftRunCreatedAt !== rightRunCreatedAt) {
        return leftRunCreatedAt - rightRunCreatedAt;
      }

      if (left.runId !== right.runId) {
        return left.runId.localeCompare(right.runId);
      }

      return left.sequence - right.sequence;
    })
    .map

(() => {
    if (!effectivePlanGraph) {
      return {
        status: "no_plan" as const,
        currentNodeId: null,
        executedNodeIds: [] as string[],
        waitingNodeIds: [] as string[],
        blockedNodeIds: [] as string[],
        message: "No accepted plan.",
      };
    }

    const effective = effectivePlanGraph;

    const executed = effective.completedNodeIds;
    const waiting = effective.nodes
      .filter((n) => n.status === "waiting_for_user")
      .map((n) => n.id);
    const blocked = Array.from(new Set([
      ...effective.blockedNodeIds,
      ...(orchestratorState?.summary.executionState === "blocked" || orchestratorState?.summary.executionState === "failed"
        ? [orchestratorState.summary.currentNodeId]
        : []),
    ].filter((value): value is string => Boolean(value))));
    const inProgress = effective.nodes.find((n) => n.status === "running");

    const allDone = effective.pendingNodeIds.length === 0 && effective.runningNodeIds.length === 0 && effective.blockedNodeIds.length === 0 && effective.failedNodeIds.length === 0;

    if (allDone) {
      return {
        status: "completed" as const,
        currentNodeId: null,
        executedNodeIds: executed,
        waitingNodeIds: waiting,
        blockedNodeIds: blocked,
        message: "All plan nodes completed.",
      };
    }

    if (task.status === "WaitingForInput" && waiting.length > 0) {
      return {
        status: "waiting_for_user" as const,
        currentNodeId: waiting[0],
        executedNodeIds: executed,
        waitingNodeIds: waiting,
        blockedNodeIds: blocked,
        message: task.blockReason
          ? (task.blockReason as { actionRequired?: string }).actionRequired ??
            "Waiting for user input"
          : "Waiting for user input",
      };
    }

    if (task.status === "WaitingForApproval") {
      return {
        status: "waiting_for_approval" as const,
        currentNodeId: inProgress?.id ?? null,
        executedNodeIds: executed,
        waitingNodeIds: waiting,
        blockedNodeIds: blocked,
        message: task.blockReason
          ? (task.blockReason as { actionRequired?: string }).actionRequired ??
            "Waiting for approval"
          : "Waiting for approval",
      };
    }

    if (task.status === "Blocked" && (blocked.length > 0 || orchestratorState?.summary.currentNodeId)) {
      return {
        status: "blocked" as const,
        currentNodeId: orchestratorState?.summary.currentNodeId ?? blocked[0] ?? null,
        executedNodeIds: executed,
        waitingNodeIds: waiting,
        blockedNodeIds: blocked,
        message: task.blockReason
          ? (task.blockReason as { actionRequired?: string }).actionRequired ??
            "Execution is blocked"
          : "Execution is blocked",
      };
    }

    return {
      status: "running" as const,
      currentNodeId: inProgress?.id ?? null,
      executedNodeIds: executed,
      waitingNodeIds: waiting,
      blockedNodeIds: blocked,
      message: "Executing plan nodes.",
    };
  })
